    private OnlineAmbientStore store,active;private AmbientCatalog catalog;private LinearLayout box;private ScrollView scroll;
    private boolean snapshotReady,loadingSnapshot,reconcile;private int snapshotGeneration,localCount;private long cacheBytes;private String snapshotKey="",operationFocus="preview",restoreFocusTag;private int operationScroll,restoreScroll=-1;private Future<?> snapshotTask;private ExecutorService worker;private Future<?> task;private boolean visible,busy;private int generation,tab;private String message="";
    interface Job {String run(OnlineAmbientStore store)throws Exception;}
    public void onCreate(Bundle b){super.onCreate(b);scale=getResources().getDisplayMetrics().widthPixels/960f;worker=Executors.newSingleThreadExecutor();store=new OnlineAmbientStore(this);show();}
    private android.content.SharedPreferences prefs(){return store.prefs();}
    @Override TextView button(String title,Runnable action){TextView b=super.button(title,action);b.setBackground(AuraTheme.states(this,px(14),AuraTheme.ACCENT));return b;}
    private void row(String key,String label,Runnable action){TextView b=button(label,action);b.setTag(key);b.setEnabled(!busy&&snapshotReady);b.setAlpha(busy||!snapshotReady?.45f:1f);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,px(44));p.bottomMargin=px(7);box.addView(b,p);}
    private void note(String text){TextView t=text(text,12,AuraTheme.MUTED);t.setPadding(0,px(5),0,px(9));box.addView(t,new LinearLayout.LayoutParams(-1,-2));}
    private void show(){String focus=getCurrentFocus()!=null&&getCurrentFocus().getTag() instanceof String?(String)getCurrentFocus().getTag():"preview";int sy=scroll==null?0:scroll.getScrollY();if(restoreFocusTag!=null&&snapshotReady){focus=restoreFocusTag;sy=restoreScroll;restoreFocusTag=null;restoreScroll=-1;}final int scrollY=sy;fullscreen();
        ensureSnapshot();
        LinearLayout container=new LinearLayout(this);container.setOrientation(1);container.setBackgroundColor(0xFF000000);container.setPadding(px(48),px(20),px(48),px(12));container.addView(text("Ambiente",30,AuraTheme.INK),new LinearLayout.LayoutParams(-1,px(49)));LinearLayout tabs=new LinearLayout(this);String[] labels={"Colecciones","Aspecto","Vídeo","Catálogo"};for(int i=0;i<labels.length;i++){final int n=i;TextView button=button((tab==i?"● ":"")+labels[i],()->{tab=n;scroll=null;show();});button.setTag("tab-"+i);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,px(39),1);if(i>0)lp.leftMargin=px(10);tabs.addView(button,lp);}container.addView(tabs);scroll=new ScrollView(this);scroll.setFillViewport(true);box=new LinearLayout(this);box.setOrientation(1);box.setPadding(px(8),px(15),px(8),px(18));scroll.addView(box);container.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        if(!message.isEmpty())note(message);
        if(tab==0){note("Elige tus fondos. Las imágenes descargadas funcionan sin conexión.");row("preview","Ver ambiente",()->startActivity(new Intent(this,AmbientActivity.class)));
        section(box,"Colecciones e imágenes");String selection=prefs().getString("collection","all"),name=selection.equals("favorites")?"Favoritos":"Todas";if(catalog!=null)for(AmbientCatalog.Collection c:catalog.collections)if(c.id.equals(selection))name=c.name;
        row("collection","Colección · "+name,this::collections);
        row("download","Descargar imágenes que faltan y usarlas",()->run("Descargando imágenes…",s->{int count=s.downloadSelection();s.prefs().edit().putBoolean("enabled",true).apply();return count+" imágenes listas · "+s.prefs().getInt("lastFetched",0)+" descargadas ahora";}));
        row("enabled",prefs().getBoolean("enabled",false)?"Fuente · imágenes descargadas":"Usar imágenes descargadas",()->{try{if(localCount==0){message="Descarga primero una colección o cambia la selección.";show();return;}prefs().edit().putBoolean("enabled",!prefs().getBoolean("enabled",false)).apply();show();}catch(Exception e){message="No hay imágenes listas.";show();}});
        row("builtin","Usar los tres paisajes integrados",()->{prefs().edit().putBoolean("enabled",false).apply();Configuration.prefs(this).edit().putBoolean("ambientRemote",false).apply();show();});
        toggle("random","Orden aleatorio",false);row("favorites","Elegir imágenes favoritas",this::favorites);
        note("Caché: "+String.format(Locale.ROOT,"%.1f",cacheBytes/1048576f)+" / 64 MiB. Se reutilizan las imágenes que no cambiaron. Las descargas son manuales.");
        row("clear","Borrar caché de imágenes online",()->run("Borrando caché…",s->{s.clear();return "Caché borrada; se conservan el catálogo y los favoritos.";}));
        }if(tab==1){section(box,"Ajustes de imagen del ambiente");
        imageChoice("Tiempo por imagen","ambientIntervalSec",new int[]{30,60,120,300,600}," s");
        row("effect","Transición · "+DisplayOptions.effectLabel(Configuration.prefs(this).getString("ambientEffect","fade")),()->chooseEffect());
        imageChoice("Duración de transición","ambientTransitionMs",new int[]{500,1000,2000}," ms");
        boolean motion=Configuration.prefs(this).getBoolean("ambientMotion",false);row("motion","Ken Burns · "+(motion?"activado":"desactivado"),()->{Configuration.prefs(this).edit().putBoolean("ambientMotion",!motion).apply();show();});imageChoice("Intensidad del zoom","ambientZoomPercent",new int[]{0,2,4}," %");
        boolean byTime=Configuration.prefs(this).getBoolean("ambientByTime",false);row("byTime","Imagen inicial según la hora · "+(byTime?"activado":"desactivado"),()->{Configuration.prefs(this).edit().putBoolean("ambientByTime",!byTime).apply();show();});imageChoice("Saturación","ambientSaturation",new int[]{75,100,125}," %");imageChoice("Contraste","ambientContrast",new int[]{75,100,125}," %");imageChoice("Brillo","ambientBrightness",new int[]{-20,-10,0,10,20}," %");note("Estos tres ajustes solo afectan a las imágenes de Ambiente. No cambian la calibración TCL, el vídeo, YouTube ni Netflix.");
        }if(tab==2){section(box,"Vídeo por streaming · MP4");
        row("videoSource",prefs().contains("videoTitle")?"Vídeo · "+prefs().getString("videoTitle",""):"Elegir vídeo del catálogo",this::chooseVideo);row("videoUrl","Usar una URL MP4 propia",this::videoUrl);
        row("videoPreview","Probar el vídeo seleccionado",()->{if(!OnlinePolicy.https(prefs().getString("videoUrl",""))){message="Elige un vídeo o introduce su URL.";show();return;}startActivity(new Intent(this,AmbientActivity.class).putExtra("video",true));});
        toggle("videoAuto","Vídeo al entrar en Ambiente",false);toggle("wifiOnly","Vídeo solo por Wi-Fi",true);
        privateChoice("Calidad máxima","videoWidth",new int[]{1280,1920},new String[]{"720p","1080p"},1920);
        privateChoice("Datos de vídeo por sesión","videoBudgetMiB",new int[]{25,100,250},new String[]{"25 MiB","100 MiB","250 MiB"},100);
        privateChoice("Tiempo máximo de vídeo","videoMinutes",new int[]{5,15,30},new String[]{"5 min","15 min","30 min"},15);
        note("Siempre silenciado. Al salir se libera el reproductor. Si falla la conexión, la calidad o el límite elegido, vuelve a imágenes. Solo Wi-Fi excluye Ethernet. Los límites cuentan los datos leídos del vídeo, no el tráfico total facturado por tu operador.");
        }if(tab==3){section(box,"Catálogo remoto");row("refresh","Actualizar catálogo",()->run("Consultando catálogo…",s->{s.refresh();return "Catálogo actualizado. Descarga solo la colección que quieras usar.";}));
        row("catalogUrl","Cambiar URL del catálogo JSON",this::catalogUrl);row("catalogReset","Restaurar catálogo oficial",()->{prefs().edit().remove("catalogUrl").apply();message="Fuente oficial seleccionada; pulsa Actualizar catálogo.";show();});
        long checked=prefs().getLong("catalogChecked",0);note(checked==0?"Todavía no se ha consultado el catálogo remoto.":"Última consulta: "+DateFormat.getDateTimeInstance().format(new Date(checked)));
        row("credits","Fuentes y licencias",this::credits);row("legacyGallery","Administrar la galería anterior",()->startActivity(new Intent(this,GalleryActivity.class)));note("El catálogo puede añadir contenido, pero no modifica tus ajustes ni activa funciones por su cuenta.");
        }TextView close=button("Volver",this::finish);box.addView(close,new LinearLayout.LayoutParams(-1,px(44)));setContentView(container);View target=container.findViewWithTag(focus);if(target!=null&&target.isEnabled())target.requestFocus();else tabs.getChildAt(tab).requestFocus();final ScrollView currentScroll=scroll;currentScroll.post(()->currentScroll.scrollTo(0,scrollY));
    }
    @Override void section(LinearLayout parent,String label){TextView title=text(label,17,AuraTheme.ACCENT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,px(38));lp.topMargin=px(6);parent.addView(title,lp);}
    private void run(String title,Job job){if(busy)return;operationFocus=getCurrentFocus()!=null&&getCurrentFocus().getTag() instanceof String?(String)getCurrentFocus().getTag():"preview";operationScroll=scroll==null?0:scroll.getScrollY();busy=true;message=title;final int request=++generation;active=new OnlineAmbientStore(this);OnlineAmbientStore operation=active;show();task=worker.submit(()->{String result;try{result=job.run(operation);}catch(Exception e){result="No se completó la operación. Los recursos válidos siguen disponibles. Revisa conexión, URL o límites.";}final String status=result;runOnUiThread(()->{if(!visible||request!=generation)return;busy=false;message=status;store=new OnlineAmbientStore(this);snapshotReady=false;snapshotKey="";restoreFocusTag=operationFocus;restoreScroll=operationScroll;show();});});}
    private void ensureSnapshot(){
        String key=prefs().getString("catalogUrl",OnlinePolicy.DEFAULT_CATALOG)+"|"+prefs().getString("collection","all")+"|"+new TreeSet<>(prefs().getStringSet("favorites",Collections.emptySet()));
        if(!key.equals(snapshotKey)){snapshotReady=false;snapshotKey=key;}
        if(!visible||busy||loadingSnapshot||snapshotReady)return;
        loadingSnapshot=true;final int request=++snapshotGeneration;final String requestedKey=key;final OnlineAmbientStore readStore=store;
        snapshotTask=worker.submit(()->{AmbientCatalog data=null;int count=0;long bytes=0;try{data=readStore.catalog();count=readStore.local(data).size();bytes=readStore.bytes();}catch(Exception ignored){}final AmbientCatalog result=data;final int ready=count;final long size=bytes;runOnUiThread(()->{if(!visible||request!=snapshotGeneration)return;loadingSnapshot=false;if(!requestedKey.equals(snapshotKey)){ensureSnapshot();return;}catalog=result;localCount=ready;cacheBytes=size;snapshotReady=true;show();});});
    }    private void toggle(String key,String name,boolean defaultValue){boolean value=prefs().getBoolean(key,defaultValue);row(key,name+" · "+(value?"activado":"desactivado"),()->{prefs().edit().putBoolean(key,!value).apply();show();});}
    private void collections(){if(catalog==null)return;ArrayList<String> names=new ArrayList<>(),ids=new ArrayList<>();names.add("Todas las imágenes");ids.add("all");names.add("Mis favoritas");ids.add("favorites");for(AmbientCatalog.Collection c:catalog.collections){boolean images=false;for(AmbientCatalog.Item m:c.items)images|=m.image();if(images){names.add(c.name);ids.add(c.id);}}new AlertDialog.Builder(this).setTitle("Colección").setItems(names.toArray(new String[0]),(d,n)->{prefs().edit().putString("collection",ids.get(n)).apply();show();}).show();}
    private void favorites(){if(catalog==null)return;ArrayList<AmbientCatalog.Item> items=new ArrayList<>();for(AmbientCatalog.Collection c:catalog.collections)for(AmbientCatalog.Item item:c.items)if(item.image())items.add(item);String[] titles=new String[items.size()];boolean[] selected=new boolean[items.size()];Set<String> values=new HashSet<>(prefs().getStringSet("favorites",Collections.emptySet()));for(int i=0;i<items.size();i++){titles[i]=items.get(i).title;selected[i]=values.contains(items.get(i).id);}new AlertDialog.Builder(this).setTitle("Imágenes favoritas").setMultiChoiceItems(titles,selected,(d,n,on)->{if(on)values.add(items.get(n).id);else values.remove(items.get(n).id);}).setPositiveButton("Guardar",(d,n)->{prefs().edit().putStringSet("favorites",values).apply();show();}).setNegativeButton("Cancelar",null).show();}
    private void imageChoice(String label,String key,int[] values,String suffix){int selected=Configuration.prefs(this).getInt(key,DisplayOptions.defaultInt(key));row(key,label+" · "+selected+suffix,()->{String[] titles=new String[values.length];for(int i=0;i<values.length;i++)titles[i]=values[i]+suffix;new AlertDialog.Builder(this).setTitle(label).setItems(titles,(d,n)->{Configuration.prefs(this).edit().putInt(key,values[n]).apply();show();}).show();});}
    private void privateChoice(String label,String key,int[] values,String[] titles,int fallback){int selected=prefs().getInt(key,fallback),position=0;for(int i=0;i<values.length;i++)if(values[i]==selected)position=i;row(key,label+" · "+titles[position],()->new AlertDialog.Builder(this).setTitle(label).setItems(titles,(d,n)->{prefs().edit().putInt(key,values[n]).apply();if(key.equals("videoWidth")&&catalog!=null){AmbientCatalog.Item item=catalog.find(prefs().getString("videoId",""));if(item!=null)prefs().edit().putString("videoUrl",item.choose(values[n]).url).apply();}show();}).show());}
    private void chooseEffect(){String[] keys={"cut","fade","slide","zoom"},names=new String[keys.length];for(int i=0;i<keys.length;i++)names[i]=DisplayOptions.effectLabel(keys[i]);new AlertDialog.Builder(this).setTitle("Transición").setItems(names,(d,n)->{Configuration.prefs(this).edit().putString("ambientEffect",keys[n]).apply();show();}).show();}
    private void chooseVideo(){if(catalog==null)return;ArrayList<AmbientCatalog.Item> list=new ArrayList<>();for(AmbientCatalog.Collection c:catalog.collections)for(AmbientCatalog.Item item:c.items)if(!item.image())list.add(item);if(list.isEmpty()){message="No hay vídeos en este catálogo. Puedes usar una URL MP4 propia.";show();return;}String[] names=new String[list.size()];for(int i=0;i<list.size();i++)names[i]=list.get(i).title;new AlertDialog.Builder(this).setTitle("Vídeo").setItems(names,(d,n)->{AmbientCatalog.Item m=list.get(n);prefs().edit().putString("videoId",m.id).putString("videoTitle",m.title).putString("videoUrl",m.choose(prefs().getInt("videoWidth",1920)).url).putString("videoCredit",m.title+" · "+m.author+" · "+m.license).apply();message="Vídeo seleccionado. Puedes probarlo antes de activar su inicio automático.";show();}).show();}
    private void editUrl(String title,String value,java.util.function.Consumer<String> save){EditText edit=new EditText(this);edit.setSingleLine(true);edit.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);edit.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2048)});edit.setText(value);edit.selectAll();new AlertDialog.Builder(this).setTitle(title).setView(edit).setPositiveButton("Guardar",(d,n)->{String url=edit.getText().toString().trim();if(!OnlinePolicy.https(url)){message="Se requiere una URL HTTPS válida, sin credenciales ni fragmentos.";show();return;}save.accept(url);show();}).setNegativeButton("Cancelar",null).show();}
    private void videoUrl(){editUrl("URL directa del MP4",prefs().getString("videoUrl",""),url->{prefs().edit().remove("videoId").putString("videoTitle","Vídeo por URL").putString("videoUrl",url).putString("videoCredit","Vídeo personalizado").apply();message="URL guardada. Los enlaces de YouTube, HLS y DASH no son MP4 directos.";});}
    private void catalogUrl(){editUrl("Catálogo JSON · esquema 2",prefs().getString("catalogUrl",OnlinePolicy.DEFAULT_CATALOG),url->{prefs().edit().putString("catalogUrl",url).apply();message="Fuente guardada. Pulsa Actualizar catálogo para consultarla.";});}
    private void credits(){if(catalog==null)return;StringBuilder text=new StringBuilder();for(AmbientCatalog.Collection c:catalog.collections)for(AmbientCatalog.Item m:c.items)text.append(m.title).append('\n').append(m.author).append(" · ").append(m.license).append('\n').append(m.source).append("\n\n");TextView t=text(text.toString(),13,AuraTheme.INK);t.setTextIsSelectable(true);t.setPadding(px(20),px(12),px(20),px(12));ScrollView content=new ScrollView(this);content.addView(t);new AlertDialog.Builder(this).setTitle("Fuentes y licencias").setView(content).setPositiveButton("Cerrar",null).show();}
    public void onStart(){super.onStart();visible=true;if(reconcile){reconcile=false;message="Operación cancelada al salir. Puedes volver a iniciarla.";restoreFocusTag=operationFocus;restoreScroll=operationScroll;}show();}
    public void onStop(){visible=false;generation++;snapshotGeneration++;loadingSnapshot=false;if(snapshotTask!=null)snapshotTask.cancel(true);if(busy){reconcile=true;snapshotReady=false;}busy=false;if(task!=null)task.cancel(true);if(active!=null)active.cancel();super.onStop();}
    public void onDestroy(){worker.shutdownNow();super.onDestroy();}
